1	"use client";
2	
3	import {
4	  Alert,
5	  Button,
6	  Card,
7	  Checkbox,
8	  Descriptions,
9	  Form,
10	  Input,
11	  Modal,
12	  Space,
13	  Table,
14	  Tag,
15	  Typography,
16	} from "antd";
17	import { useCallback, useEffect, useMemo, useState } from "react";
18	
19	import { ErrorState, LoadingState } from "@/components/RequestState";
20	import {
21	  getRecoveryOverview,
22	  startRecoveryDrill,
23	  type RecoveryComponent,
24	  type RecoveryDrill,
25	  type RecoveryOverview,
26	} from "@/lib/api/client";
27	
28	const components: Array<{ label: string; value: RecoveryComponent }> = [
29	  { label: "PostgreSQL", value: "postgresql" },
30	  { label: "Temporal", value: "temporal" },
31	  { label: "MinIO", value: "minio" },
32	  { label: "Kafka", value: "kafka" },
33	  { label: "Redis", value: "redis" },
34	  { label: "GitOps / Registry", value: "gitops_registry" },
35	  { label: "模型服务", value: "model_service" },
36	];
37	
38	const componentNames = new Map(components.map((item) => [item.value, item.label]));
39	const evidenceColors: Record<string, string> = {
40	  COMPLIANT: "green",
41	  MISSING: "default",
42	  STALE: "orange",
43	  FAILED: "red",
44	};
45	const evidenceLabels: Record<string, string> = {
46	  COMPLIANT: "证据合规",
47	  MISSING: "缺少证据",
48	  STALE: "证据过期",
49	  FAILED: "验证失败",
50	};
51	const failureLabels: Record<string, string> = {
52	  postgresql_unavailable: "PostgreSQL 不可用",
53	  kafka_unavailable: "Kafka 不可用",
54	  temporal_unavailable: "Temporal 不可用",
55	  minio_unavailable: "MinIO 不可用",
56	  redis_unavailable: "Redis 不可用",
57	  model_service_unavailable: "模型服务不可用",
58	  opa_unavailable: "OPA 不可用",
59	  vault_unavailable: "Vault 不可用",
60	  sse_disconnected: "SSE 断线",
61	  gpu_out_of_memory: "GPU OOM",
62	};
63	const policyTranslations: Record<string, { behavior: string; prohibited: string }> = {
64	  postgresql_unavailable: {
65	    behavior: "拒绝业务写入、Readiness 失败并告警",
66	    prohibited: "仅凭缓存继续审批或修改设备状态",
67	  },
68	  kafka_unavailable: {
69	    behavior: "合法在线事务与 Outbox 继续，恢复后重放追平",
70	    prohibited: "仅因消息发送失败回滚已提交的业务事务",
71	  },
72	  temporal_unavailable: {
73	    behavior: "新编排请求进入等待，高风险动作停止",
74	    prohibited: "在 API 内绕过工作流直接执行副作用",
75	  },
76	  minio_unavailable: {
77	    behavior: "阻止附件确认，保留可查询元数据",
78	    prohibited: "把无哈希临时文件当作正式证据",
79	  },
80	  redis_unavailable: {
81	    behavior: "回源权威存储、保守限流，必要时重新认证",
82	    prohibited: "把缓存缺失解释为工单或审批丢失",
83	  },
84	  model_service_unavailable: {
85	    behavior: "切换合格稳定模型或检索加人工模式",
86	    prohibited: "让未经评测的模型静默接管",
87	  },
88	  opa_unavailable: {
89	    behavior: "写操作和高风险工具失败关闭",
90	    prohibited: "为保持可用性放行全部请求",
91	  },
92	  vault_unavailable: {
93	    behavior: "已有租约实例仅运行至过期，新实例保持未就绪",
94	    prohibited: "在配置中回退到明文 Secret",
95	  },
96	  sse_disconnected: {
97	    behavior: "通过 Last-Event-ID 续传或读取权威快照",
98	    prohibited: "重启整个 Run 并重复产生副作用",
99	  },
100	  gpu_out_of_memory: {
101	    behavior: "有界排队、拒绝超预算任务或切换合格模型",
102	    prohibited: "无限重试形成雪崩",
103	  },
104	};
105	
106	export function RecoveryGovernancePanel() {
107	  const [overview, setOverview] = useState<RecoveryOverview>();
108	  const [legalActions, setLegalActions] = useState<string[]>([]);
109	  const [requestId, setRequestId] = useState<string>();
110	  const [error, setError] = useState<unknown>();
111	  const [modalOpen, setModalOpen] = useState(false);
112	  const [submitting, setSubmitting] = useState(false);
113	  const [receipt, setReceipt] = useState<RecoveryDrill>();
114	  const [form] = Form.useForm<{
115	    scenario: string;
116	    scope: RecoveryComponent[];
117	    outageDetectedAt: string;
118	  }>();
119	
120	  const load = useCallback(async () => {
121	    try {
122	      const result = await getRecoveryOverview();
123	      setOverview(result.overview);
124	      setLegalActions(result.legalActions);
125	      setRequestId(result.requestId);
126	      setError(undefined);
127	    } catch (cause) {
128	      setError(cause);
129	    }
130	  }, []);
131	
132	  useEffect(() => {
133	    void load();
134	  }, [load]);
135	
136	  const canManage = legalActions.includes("MANAGE_RECOVERY_DRILL");
137	  const failedComponents = useMemo(
138	    () => overview?.components.filter((item) => item.evidence_status !== "COMPLIANT").length ?? 0,
139	    [overview],
140	  );
141	
142	  function openDrill() {
143	    const now = new Date();
144	    now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
145	    form.setFieldsValue({
146	      scenario: "quarterly-cross-component",
147	      scope: components.filter((item) => item.value !== "redis").map((item) => item.value),
148	      outageDetectedAt: now.toISOString().slice(0, 16),
149	    });
150	    setModalOpen(true);
151	  }
152	
153	  async function submitDrill() {
154	    const values = await form.validateFields();
155	    setSubmitting(true);
156	    try {
157	      const result = await startRecoveryDrill(
158	        {
159	          scenario: values.scenario,
160	          scope: values.scope,
161	          outage_detected_at: new Date(values.outageDetectedAt).toISOString(),
162	        },
163	        `recovery-drill-${Date.now()}-${crypto.randomUUID()}`,
164	      );
165	      setReceipt(result.drill);
166	      setRequestId(result.requestId);
167	      setModalOpen(false);
168	      await load();
169	    } catch (cause) {
170	      setError(cause);
171	    } finally {
172	      setSubmitting(false);
173	    }
174	  }
175	
176	  return (
177	    <Card
178	      title="灾难恢复、备份证据与演练"
179	      extra={canManage ? <Button type="primary" onClick={openDrill}>发起恢复演练</Button> : null}
180	    >
181	      <Space direction="vertical" size="large" style={{ width: "100%" }}>
182	        {error ? <ErrorState error={error} onRetry={() => void load()} /> : null}
183	        {!overview && !error ? <LoadingState label="正在读取恢复治理证据" /> : null}
184	        {receipt ? (
185	          <Alert
186	            showIcon
187	            type="info"
188	            closable
189	            onClose={() => setReceipt(undefined)}
190	            message={`恢复演练 ${receipt.drill_id} 已进入 RUNNING`}
191	            description="备份与恢复执行器必须提交逐组件恢复结果；页面发起演练不会把未验证结果直接标记为成功。"
192	          />
193	        ) : null}
194	        {overview ? (
195	          <>
196	            <Alert
197	              showIcon
198	              type={overview.release_allowed ? "success" : "warning"}
199	              message={overview.release_gate_enforced
200	                ? overview.release_allowed ? "恢复发布门禁通过" : "恢复发布门禁未通过"
201	                : "当前环境只观察恢复姿态，不执行发布阻断"}
202	              description={`异常组件：${failedComponents}；PostgreSQL 月度恢复验证${overview.monthly_postgres_restore_due ? "已到期" : "有效"}；跨组件季度演练${overview.quarterly_cross_component_drill_due ? "已到期" : "有效"}。`}
203	            />
204	            <Table
205	              rowKey="component"
206	              pagination={false}
207	              dataSource={overview.components}
208	              scroll={{ x: 1050 }}
209	              columns={[
210	                {
211	                  title: "组件",
212	                  dataIndex: "component",
213	                  width: 160,
214	                  render: (value: RecoveryComponent) => componentNames.get(value) ?? value,
215	                },
216	                {
217	                  title: "RPO",
218	                  dataIndex: "rpo_seconds",
219	                  width: 130,
220	                  render: (value: number | null) => value == null ? "缓存可丢失" : formatSeconds(value),
221	                },
222	                {
223	                  title: "RTO",
224	                  dataIndex: "rto_seconds",
225	                  width: 120,
226	                  render: (value: number) => formatSeconds(value),
227	                },
228	                {
229	                  title: "证据状态",
230	                  dataIndex: "evidence_status",
231	                  width: 130,
232	                  render: (value: string) => (
233	                    <Tag color={evidenceColors[value]}>{evidenceLabels[value] ?? value}</Tag>
234	                  ),
235	                },
236	                {
237	                  title: "最新恢复点",
238	                  width: 200,
239	                  render: (_, item) => item.latest_evidence
240	                    ? new Date(item.latest_evidence.recovery_point_at).toLocaleString()
241	                    : "—",
242	                },
243	                { title: "恢复方式", dataIndex: "recovery_method" },
244	              ]}
245	            />
246	            <Card size="small" title={`最近恢复演练（${overview.recent_drills.length}）`}>
247	              <Table
248	                rowKey="drill_id"
249	                size="small"
250	                pagination={false}
251	                dataSource={overview.recent_drills}
252	                locale={{ emptyText: "尚未登记恢复演练" }}
253	                columns={[
254	                  { title: "场景", dataIndex: "scenario" },
255	                  {
256	                    title: "范围",
257	                    dataIndex: "scope",
258	                    render: (values: RecoveryComponent[]) => values
259	                      .map((value) => componentNames.get(value) ?? value)
260	                      .join("、"),
261	                  },
262	                  {
263	                    title: "状态",
264	                    dataIndex: "status",
265	                    width: 110,
266	                    render: (value: string) => (
267	                      <Tag color={value === "PASSED" ? "green" : value === "FAILED" ? "red" : "blue"}>
268	                        {value}
269	                      </Tag>
270	                    ),
271	                  },
272	                  {
273	                    title: "开始时间",
274	                    dataIndex: "started_at",
275	                    width: 190,
276	                    render: (value: string) => new Date(value).toLocaleString(),
277	                  },
278	                  {
279	                    title: "阻断项",
280	                    dataIndex: "blocker_codes",
281	                    render: (values: string[]) => values.length ? values.join("；") : "—",
282	                  },
283	                ]}
284	              />
285	            </Card>
286	            <Card size="small" title="受控降级策略">
287	              <Table
288	                rowKey="failure"
289	                size="small"
290	                pagination={false}
291	                dataSource={overview.degradation_policies}
292	                scroll={{ x: 1000 }}
293	                columns={[
294	                  {
295	                    title: "故障",
296	                    dataIndex: "failure",
297	                    width: 190,
298	                    render: (value: string) => failureLabels[value] ?? value,
299	                  },
300	                  {
301	                    title: "系统行为",
302	                    dataIndex: "system_behavior",
303	                    render: (value: string, item) => policyTranslations[item.failure]?.behavior ?? value,
304	                  },
305	                  {
306	                    title: "禁止行为",
307	                    dataIndex: "prohibited_behavior",
308	                    render: (value: string, item) => (
309	                      <Typography.Text type="danger">
310	                        {policyTranslations[item.failure]?.prohibited ?? value}
311	                      </Typography.Text>
312	                    ),
313	                  },
314	                ]}
315	              />
316	            </Card>
317	            <Typography.Text type="secondary">
318	              恢复策略 {overview.policy_version} · 请求 ID {requestId}
319	            </Typography.Text>
320	          </>
321	        ) : null}
322	      </Space>
323	
324	      <Modal
325	        title="发起受控恢复演练"
326	        open={modalOpen}
327	        okText="创建演练"
328	        cancelText="取消"
329	        confirmLoading={submitting}
330	        onOk={() => void submitDrill()}
331	        onCancel={() => setModalOpen(false)}
332	      >
333	        <Alert
334	          showIcon
335	          type="warning"
336	          message="此操作只建立演练状态和证据边界，不会直接删除、恢复或切换生产数据。"
337	          style={{ marginBottom: 16 }}
338	        />
339	        <Form form={form} layout="vertical">
340	          <Form.Item
341	            name="scenario"
342	            label="演练场景标识"
343	            rules={[{ required: true }, { pattern: /^[A-Za-z0-9][A-Za-z0-9._:/-]*$/ }]}
344	          >
345	            <Input placeholder="quarterly-cross-component" />
346	          </Form.Item>
347	          <Form.Item name="scope" label="恢复范围" rules={[{ required: true }]}>
348	            <Checkbox.Group options={components} />
349	          </Form.Item>
350	          <Form.Item name="outageDetectedAt" label="模拟故障发现时间" rules={[{ required: true }]}>
351	            <Input type="datetime-local" />
352	          </Form.Item>
353	        </Form>
354	        <Descriptions size="small" column={1} bordered>
355	          <Descriptions.Item label="成功条件">
356	            每个组件均满足 RPO/RTO、备份证据和全部一致性检查。
357	          </Descriptions.Item>
358	          <Descriptions.Item label="失败行为">
359	            任何缺失或失败都记录明确 blocker，不能人工改写成 PASSED。
360	          </Descriptions.Item>
361	        </Descriptions>
362	      </Modal>
363	    </Card>
364	  );
365	}
366	
367	function formatSeconds(seconds: number): string {
368	  if (seconds === 0) return "0 秒（版本不丢失）";
369	  if (seconds % 3600 === 0) return `${seconds / 3600} 小时`;
370	  if (seconds % 60 === 0) return `${seconds / 60} 分钟`;
371	  return `${seconds} 秒`;
372	}
