      </Col>
      <Col span={12}>
        <Form.Item name={digestName} label={`${label} SHA-256`} rules={[{ required: true }, { pattern: digestRule }]}>
          <Input placeholder="sha256:..." />
        </Form.Item>
      </Col>
    </Row>
  );
}

