986	function formatTime(value: string): string {
987	  return new Intl.DateTimeFormat("zh-CN", {
988	    dateStyle: "short",
989	    timeStyle: "short",
990	    hour12: false,
991	  }).format(new Date(value));
992	}
993	
994	function percent(value: number | null | undefined): string {
995	  return value == null ? "无证据" : `${(value * 100).toFixed(1)}%`;
996	}
997	
