999	  return value == null ? "无证据" : `${value.toFixed(1)} 分钟`;
1000	}
1001	
1002	function rulStatusColor(value: string): string {
1003	  if (value === "ACCEPTED") return "green";
1004	  if (value === "REJECTED") return "red";
1005	  return "orange";
1006	}
1007	
1008	function rulStatusLabel(value: string): string {
1009	  if (value === "ACCEPTED") return "已独立接受";
1010	  if (value === "REJECTED") return "已拒绝";
1011	  return "等待独立复核";
1012	}
1013	
1014	function rulCalibrationStatusColor(value: string): string {
1015	  if (value === "STABLE") return "green";
1016	  if (value === "RETRAINING_RECOMMENDED") return "red";
1017	  return "gold";
1018	}
1019	
1020	function rulCalibrationStatusLabel(value: string): string {
1021	  if (value === "STABLE") return "校准稳定";
1022	  if (value === "RETRAINING_RECOMMENDED") return "建议再训练";
1023	  return "证据不足";
1024	}
1025	
1026	function rulCalibrationReasonLabel(value: string): string {
1027	  const labels: Record<string, string> = {
1028	    MINIMUM_30_LABELED_OUTCOMES_NOT_MET: "不足 30 条真实结果",
1029	    ONLINE_CALIBRATION_WITHIN_GATES: "近期误差与覆盖在门禁内",
1030	    RECENT_MEDIAN_MAE_REGRESSION: "近期中位 MAE 回退",
1031	    RECENT_INTERVAL_COVERAGE_BELOW_FLOOR: "近期 P10–P90 覆盖低于 70%",
1032	  };
1033	  return labels[value] ?? value;
1034	}
